#include "feature.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static tf_model m;
static uint8_t runtime[76800];
static unsigned checks, failures, groups;
static int delivered_empty;
#define CHECK(x) do {checks++;if(!(x)){failures++;printf("FAIL line=%d %s\n",__LINE__,#x);}} while(0)
#define A(x) (TF_RAM_BASE+UINT32_C(x))
static void b(uint32_t a,uint8_t v){m.ram[a-TF_RAM_BASE]=v;m.known[a-TF_RAM_BASE]=255;}
static uint8_t r(uint32_t a){return m.ram[a-TF_RAM_BASE];}
static void w(uint32_t a,uint32_t v){unsigned i;for(i=0;i<4;i++)b(a+i,(uint8_t)(v>>(8*i)));}
static uint32_t rw(uint32_t a){return (uint32_t)r(a)|((uint32_t)r(a+1)<<8)|((uint32_t)r(a+2)<<16)|((uint32_t)r(a+3)<<24);}
static int rom(void *p,unsigned off,uint8_t task,uint16_t mask,uint32_t ticks){(void)p;(void)task;(void)mask;(void)ticks;return off==88?1:0;}
static int tx(void *p,const tf_frame *f){(void)p;(void)f;return 1;}
static void delivery(void *p,tf_model *q,uint32_t cb,uint32_t arg){(void)p;(void)arg;if(cb==0xdead){delivered_empty=rw(TF_REGISTRY+4)==0;CHECK(q==&m);(void)tf_schedule(q,0xbeef,0,0,0);}}
static void fresh(void){tf_backend backend={NULL,rom,tx,delivery,1};tf_init(&m,runtime,sizeof(runtime),&backend);}
static void frame(tf_frame *f,uint16_t id){memset(f,0,sizeof(*f));memset(f->known,255,12);f->available=12;f->value[0]=(uint8_t)id;f->value[1]=(uint8_t)(id>>8);f->value[2]=8;}
static void group(const char *s){groups++;printf("GROUP %s\n",s);}
static void test_startup(void){unsigned i;group("native data and BSS preserve external RAM unknown");fresh();for(i=0;i<136;i++){CHECK(r(TF_GP+i)==runtime[0x127e0+i]);CHECK(m.known[0x4000+i]==255);}CHECK(m.known[0x4088]==255);CHECK(m.known[0xc94f]==255);CHECK(m.known[0xc950]==0);CHECK(m.known[0x200]==0);}
static void test_scheduler(void){unsigned i;group("replace nonzero delay, zero duplicates, clear before callback, full slots");fresh();CHECK(tf_schedule(&m,0xd62e,0,10,123)==0);CHECK(tf_schedule(&m,0xd62e,0,20,456)==0);CHECK(m.free_requests==1);CHECK(rw(TF_REGISTRY+8)==456);CHECK(m.last_ticks==32);CHECK(tf_schedule(&m,0xd62e,1,0,0)==0);CHECK(r(TF_REGISTRY+12)==0);CHECK(rw(TF_REGISTRY+16)==0xd62e);CHECK(tf_cancel(&m,0xd62e)==0);CHECK(rw(TF_REGISTRY+4)==0);CHECK(rw(TF_REGISTRY+16)==0xd62e);CHECK(tf_dispatch(&m,2)==0);CHECK(r(A(0xbf6a))==20);fresh();delivered_empty=0;CHECK(tf_schedule(&m,0xdead,0,10,0)==0);CHECK(tf_dispatch(&m,3)==2);CHECK(delivered_empty);CHECK(rw(TF_REGISTRY+4)==0xbeef);CHECK(m.unknown_effects!=0);fresh();for(i=0;i<15;i++)CHECK(tf_schedule(&m,0x1000+i,0,0,0)==0);CHECK(tf_schedule(&m,0xffff,0,10,0)==1);CHECK(m.schedule_requests==15);CHECK(tf_cancel(&m,0xffff)==1);fresh();CHECK(tf_schedule(&m,0xd62e,1,10,9)==0);CHECK(tf_dispatch(&m,1)==0);CHECK(rw(TF_REGISTRY+4)==0xd62e);CHECK(rw(TF_REGISTRY+8)==9);fresh();CHECK(tf_schedule(&m,0xd62e,256,10,0)==0);CHECK(m.last_rom_offset==556);CHECK(r(TF_REGISTRY)==0);CHECK(tf_dispatch(&m,1)==0);CHECK(rw(TF_REGISTRY+4)==0);}
static void test_hold(void){group("threshold pause, changing threshold, unsigned wrap, invalid latch");fresh();CHECK(tf_hold(&m,1,7,A(0xbf70),A(0xbf74),0xffffff00)==0);CHECK(r(A(0xbf70))==1);CHECK(tf_hold(&m,0,0,A(0xbf70),A(0xbf74),123)==0);CHECK(r(A(0xbf70))==1);CHECK(rw(A(0xbf74))==0xffffff00);CHECK(tf_hold(&m,1,7,A(0xbf70),A(0xbf74),0x3e8)==7);CHECK(r(A(0xbf70))==2);CHECK(tf_hold(&m,1,7,A(0xbf70),A(0xbf74),5000)==0);CHECK(tf_hold(&m,1,0,A(0xbf70),A(0xbf74),6000)==0);CHECK(r(A(0xbf70))==0);b(A(0xbf70),7);CHECK(tf_hold(&m,1,0,A(0xbf70),A(0xbf74),0)==0);CHECK(r(A(0xbf70))==7);b(A(0xbf70),1);w(A(0xbf74),100);CHECK(tf_hold(&m,2,1,A(0xbf70),A(0xbf74),2099)==0);CHECK(tf_hold(&m,2,1,A(0xbf70),A(0xbf74),2100)==1);}
static void test_admission(void){group("failed admission retains pending, delayed callback reads new request");fresh();b(A(0xbf7c),3);CHECK(tf_admit(&m,4,1,0)==0);CHECK(r(A(0xbf7c))==3);CHECK(tf_admit(&m,1,511,0)==1);CHECK(r(A(0xbf8d))==2);tf_delay_bridge(&m,100);CHECK(tf_admit(&m,4,0,0)==1);tf_delay_bridge(&m,1000);CHECK(m.last_ticks==1600);CHECK(tf_dispatch(&m,1)==0);CHECK(r(A(0xbf6a))==4);CHECK(r(A(0xbf7c))==0);fresh();CHECK(tf_admit(&m,1,0,0)==1);tf_delay_bridge(&m,100);CHECK(tf_admit(&m,25,0,1)==1);CHECK(r(A(0xbf96))==1);CHECK(rw(TF_REGISTRY+4)==0xd69a);b(A(0xbf7c),2);CHECK(tf_dispatch(&m,1)==0);CHECK(r(A(0xbf6a))==2);b(A(0xbf7c),20);tf_bridge(&m);CHECK(r(A(0xbf7c))==0);CHECK(r(A(0xbf6a))==2);}
static void test_doors(void){
 static const uint8_t want[24][3]={{0xc5,0xd3,0xad},{0xc5,0xd3,0xad},{0x65,0xd3,0xad},{0xa5,0xd3,0xad},{0xa5,0xd6,0xad},{0xa5,0xd3,0xad},{0xa5,0xf3,0xad},{0xa5,0xf3,0xad},{0xa5,0xdb,0xad},{0xa5,0x93,0xad},{0xa5,0x93,0xad},{0xa5,0xd3,0xac},{0xc5,0xb6,0xad},{0x65,0xdb,0xac},{0x45,0x92,0xa4},{0xa5,0xb6,0xad},{0xa5,0xb3,0xad},{0xa5,0xb3,0xad},{0xa5,0xdb,0xac},{0x65,0xd3,0xad},{0xa5,0xd3,0xad},{0xa5,0xdb,0xad},{0xa5,0xd3,0xac},{0xa5,0xd3,0xad}};
 unsigned i;tf_frame f;group("all24 door table cases, TX gate consumes pending, generic followup");
 for(i=0;i<24;i++){fresh();frame(&f,0x1f9);f.value[3]=0xa5;f.value[4]=0xd3;f.value[5]=0xad;b(A(0xbf6a),(uint8_t)(i+1));b(A(0xbf6b),1);b(A(0xbf6c),0);b(A(0xbf6d),1);b(A(0xbf6e),1);b(A(0xbf6f),1);tf_door_consume(&m,&f,7);CHECK(f.value[3]==want[i][0]);CHECK(f.value[4]==want[i][1]);CHECK(f.value[5]==want[i][2]);CHECK(r(A(0xbf6a))==0);CHECK(m.tx_requests==1);}
 fresh();frame(&f,0x1f9);b(A(0xbf6a),1);tf_door_consume(&m,&f,1);CHECK(f.value[3]==0x60);CHECK(rw(TF_REGISTRY+4)==0xd62e);b(A(0xbf6a),2);CHECK(tf_dispatch(&m,1)==0);CHECK(r(A(0xbf6a))==20);fresh();frame(&f,0x1f9);b(A(0xbf6a),25);b(A(0xc29c),8);tf_door_consume(&m,&f,7);CHECK(r(A(0xbf6a))==0);CHECK(m.tx_requests==1);CHECK(m.tx_gate_refused==1);CHECK(f.value[3]==0);
}
static void test_observers(void){group("102 and103 source mapping, raw invalid preserves confirmed");fresh();tf_observe_pair(&m,0x102,0x21,0);CHECK(r(A(0xbf6b))==1);CHECK(r(A(0xbf6d))==2);CHECK(r(A(0xbf66))==1);CHECK(r(A(0xbf68))==2);tf_observe_pair(&m,0x103,0x12,1);CHECK(r(A(0xbf6c))==2);CHECK(r(A(0xbf6e))==1);CHECK(r(A(0xbf67))==2);CHECK(r(A(0xbf69))==1);tf_observe_pair(&m,0x102,0xf3,0);CHECK(r(A(0xbf6b))==3);CHECK(r(A(0xbf6d))==15);CHECK(r(A(0xbf66))==1);CHECK(r(A(0xbf68))==2);}
static void test_body273(void){tf_frame f;group("fog priority, BF95 d3, pre-TX clears, persistent clearing");fresh();frame(&f,0x273);f.value[3]=8;b(A(0xbf99),1);b(A(0xbf93),1);tf_body273(&m,&f,0);CHECK((f.value[3]&8)==0);CHECK(m.tx_requests==1);b(A(0xbf99),0);tf_body273(&m,&f,0);CHECK((f.value[3]&8)==8);fresh();frame(&f,0x273);b(A(0xbf95),1);b(A(0xbf96),1);b(A(0xc29c),8);tf_body273(&m,&f,0);CHECK(f.value[6]==0x80);CHECK(f.value[10]==0);CHECK(r(A(0xbf95))==0);CHECK(r(A(0xbf96))==0);CHECK(m.tx_gate_refused==1);fresh();frame(&f,0x273);f.value[3]=4;f.value[5]=1;f.value[10]=0x80;b(A(0xbf92),1);b(A(0xbf94),1);tf_body273(&m,&f,0);CHECK(f.value[3]==0);CHECK(f.value[5]==0);CHECK(f.value[10]==8);CHECK(r(A(0xbf92))==1);CHECK(r(A(0xbf94))==1);}
static void test_229(void){tf_frame f;group("229 full request index, terminal TX, neutral phase, malformed unknown");fresh();frame(&f,0x229);f.value[4]=0xd7;f.value[5]=0xad;tf_ceba(&m,5,1,1);tf_229(&m,&f);CHECK(r(A(0xbf34))==0);CHECK(r(A(0xbf37))==0);CHECK(r(A(0xbf36))==255);CHECK(f.value[4]==0x88);CHECK(f.value[5]==0xad);CHECK(f.value[3]==runtime[0x19d10-0x8000+88]);CHECK(m.tx_requests==1);fresh();frame(&f,0x229);tf_ceba(&m,2,2,0);tf_229(&m,&f);CHECK(f.value[4]==0x21);CHECK(r(A(0xbf37))==1);tf_229(&m,&f);CHECK(f.value[4]==2);CHECK(r(A(0xbf37))==1);tf_229(&m,&f);CHECK(f.value[4]==3);tf_229(&m,&f);CHECK(f.value[4]==0x24);CHECK(r(A(0xbf34))==0);fresh();tf_ceda(&m,1,0);CHECK(rw(A(0xbf34))==0x01000501);fresh();frame(&f,0x229);f.value[4]=15;tf_ceba(&m,239,1,1);tf_229(&m,&f);CHECK(f.known[3]==0);CHECK(m.last_unknown_address==0x1ac00);CHECK(m.tx_requests==1);fresh();frame(&f,0x229);tf_ceba(&m,3,0,1);tf_229(&m,&f);CHECK(r(A(0xbf37))==255);CHECK(r(A(0xbf34))==1);}
static void test_checksum678(void){tf_frame f;uint8_t sum=0;unsigned i;group("678 nonconsecutive valid events, fifth same-frame send, DLC overread");fresh();frame(&f,0x678);f.value[3]=0x7e;tf_fed4(&m,1,1);for(i=0;i<3;i++)tf_678_observe(&m,&f);CHECK(r(TF_GP+302)==3);f.value[3]^=1;tf_678_observe(&m,&f);CHECK(r(TF_GP+302)==3);f.value[3]^=1;tf_678_observe(&m,&f);tf_678_observe(&m,&f);CHECK(r(TF_GP+354)==1);CHECK(r(TF_GP+302)==0);tf_678_consume(&m,&f);CHECK(f.value[4]==0x11);CHECK(f.value[3]==0x8f);CHECK(r(TF_GP+301)==9);CHECK(r(TF_GP+300)==1);frame(&f,0x678);f.value[2]=9;f.value[11]=2;CHECK(tf_checksum(&f,&sum)==1);CHECK(sum==0x80);f.value[2]=10;CHECK(tf_checksum(&f,&sum)==TF_UNKNOWN);f.value[2]=0;CHECK(tf_checksum(&f,&sum)==1);CHECK(sum==0x7e);fresh();frame(&f,0x678);f.value[3]=0x7e;b(TF_GP+302,255);tf_678_observe(&m,&f);CHECK(r(TF_GP+302)==0);CHECK(r(TF_GP+354)==0);}
static void test_threshold_reset(void){group("raw threshold boundary, separate reset scopes retain latch and timers");fresh();b(A(0xc298),1);b(TF_GP+277,1);tf_threshold118(&m,50);CHECK(r(TF_GP+277)==0);tf_threshold118(&m,51);CHECK(r(TF_GP+277)==1);b(A(0xc298),0);tf_threshold118(&m,0);CHECK(r(TF_GP+277)==1);tf_fed4(&m,4,1);b(TF_GP+354,1);CHECK(tf_schedule(&m,0xd3b2,0,500,0)==0);tf_reset_scope(&m,0xfee4);CHECK(r(TF_GP+300)==0);CHECK(r(TF_GP+301)==0);CHECK(r(TF_GP+354)==1);CHECK(rw(TF_REGISTRY+4)==0xd3b2);tf_ceba(&m,5,10,1);b(TF_GP+228,4);tf_reset_scope(&m,0xcf4c);CHECK(r(A(0xbf34))==0);CHECK(r(TF_GP+228)==4);CHECK(rw(TF_REGISTRY+4)==0xd3b2);m.backend.memory_contracts=0;b(A(0xbf34),1);tf_reset_scope(&m,0xcf4c);CHECK(m.known[0xbf34]==0);CHECK(m.unknown_effects!=0);}
static void test_fog_callbacks(void){group("fog callback requeues after flags reset and paired disable controls cancel");fresh();tf_fog_set(&m,0xf53c,1);CHECK(r(A(0xbf99))==1);CHECK(r(A(0xbf9d))==1);CHECK(rw(TF_REGISTRY+4)==0xf384);CHECK(m.last_ticks==80);tf_reset_scope(&m,0xf6fe);CHECK(r(A(0xbf99))==0);CHECK(rw(TF_REGISTRY+4)==0xf384);CHECK(tf_dispatch(&m,1)==0);CHECK(rw(TF_REGISTRY+4)==0xf384);CHECK(r(A(0xbf9d))==1);CHECK(m.tx_requests==2);tf_fog_set(&m,0xf53c,0);CHECK(rw(TF_REGISTRY+4)==0);fresh();tf_fog_set(&m,0xf5a0,1);CHECK(r(A(0xbfa2))==1);CHECK(m.last_ticks==216);CHECK(tf_dispatch(&m,1)==0);CHECK(r(A(0xbfa2))==2);CHECK(tf_dispatch(&m,1)==0);CHECK(tf_dispatch(&m,1)==0);CHECK(r(A(0xbfa2))==0);CHECK(m.last_ticks==2400);}
static void test_free_slot_stale_argument(void){group("new free slot overwrites stale argument without deallocation");fresh();w(TF_REGISTRY+8,123);CHECK(tf_schedule(&m,0xdead,0,10,456)==0);CHECK(m.free_requests==0);CHECK(rw(TF_REGISTRY+8)==456);fresh();m.known[0xbe10]=0;CHECK(tf_schedule(&m,0xdead,0,10,456)==0);CHECK(rw(TF_REGISTRY+8)==456);CHECK(m.known[0xbe10]==255);}
static void test_known_mask_and_short_circuit(void){tf_frame f;group("OR establishes known one bits and native short circuits preserve later effects");fresh();frame(&f,0x273);f.known[6]=0;b(A(0xbf95),1);tf_body273(&m,&f,0);CHECK(f.value[6]==0x80);CHECK(f.known[6]==0x80);fresh();frame(&f,0x273);f.value[5]=1;f.known[5]=1;f.known[3]=0;f.known[10]=0;b(A(0xbf92),1);tf_body273(&m,&f,0);CHECK((f.known[3]&4)==4);CHECK((f.known[10]&0x80)==0x80);CHECK(m.tx_requests==1);fresh();frame(&f,0x273);m.known[0xbf40]=0;b(A(0xbf95),1);tf_body273(&m,&f,0);CHECK(f.value[6]==0x80);CHECK(r(A(0xbf95))==0);CHECK(m.tx_requests==1);}
static void test_unknown_data_retains_unconditional_effects(void){tf_frame f;group("unknown counter or table data does not invent native early return");fresh();frame(&f,0x678);f.known[4]=0xf0;tf_fed4(&m,1,0);b(TF_GP+354,1);tf_678_consume(&m,&f);CHECK((f.value[4]&0xf0)==0x10);CHECK(f.known[4]==0xf0);CHECK(f.known[3]==0);CHECK(r(TF_GP+301)==0);CHECK(m.tx_requests==1);fresh();frame(&f,0x229);tf_ceba(&m,2,1,1);m.known[0xbf37]=0;tf_229(&m,&f);CHECK(f.value[4]==0x21);CHECK(f.known[4]==255);CHECK(m.known[0xbf37]==0);CHECK(m.known[0xbf34]!=255);CHECK(m.tx_requests==1);fresh();frame(&f,0x1f9);b(A(0xbf6a),1);m.known[0xbf6b]=0;tf_door_consume(&m,&f,7);CHECK(r(A(0xbf6a))==0);CHECK((f.value[3]&0x40)==0x40);CHECK(f.known[3]==0x5f);CHECK(m.tx_requests==1);}
static void test_unknown_old_value_joins(void){group("both equality branches establish confirmed and threshold poststate");fresh();m.known[0xbf66]=0;tf_observe_pair(&m,0x102,1,0);CHECK(r(A(0xbf66))==1);CHECK(m.known[0xbf66]==255);b(A(0xc298),1);m.known[0x4115]=0;tf_threshold118(&m,51);CHECK(r(TF_GP+277)==1);CHECK(m.known[0x4115]==255);}
static void test_full_registers(void){tf_frame f;group("full32 active, force and enabled survive byte stores without narrowing branch");fresh();CHECK(tf_hold(&m,1,256,A(0xbf70),A(0xbf74),100)==0);CHECK(r(A(0xbf70))==1);CHECK(tf_hold(&m,1,256,A(0xbf70),A(0xbf74),1100)==256);b(A(0xbf70),1);CHECK(tf_hold(&m,1,UINT32_C(0xffffffff),A(0xbf70),A(0xbf74),1100)==INT64_C(4294967295));fresh();frame(&f,0x273);tf_body273(&m,&f,256);CHECK(m.tx_requests==1);fresh();tf_fog_set(&m,0xf53c,256);CHECK(r(A(0xbf99))==0);CHECK(r(A(0xbf9d))==1);CHECK(rw(TF_REGISTRY+4)==0xf384);CHECK(m.tx_requests==1);}
static void test_no_dispatchable_bit(void){group("8FF8 returns zero when no event bit0..14 is set");fresh();CHECK(tf_dispatch(&m,0x8000)==0);CHECK(m.callback_calls==0);}
int main(int argc,char **argv){FILE *p;if(argc!=2){puts("runtime path required");return 2;}p=fopen(argv[1],"rb");if(!p||fread(runtime,1,sizeof(runtime),p)!=sizeof(runtime)){puts("runtime read failed");if(p)fclose(p);return 2;}fclose(p);test_startup();test_scheduler();test_hold();test_admission();test_doors();test_observers();test_body273();test_229();test_checksum678();test_threshold_reset();test_fog_callbacks();test_free_slot_stale_argument();test_known_mask_and_short_circuit();test_unknown_data_retains_unconditional_effects();test_unknown_old_value_joins();test_full_registers();test_no_dispatchable_bit();printf("FEATURE_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
